package com.jbitmstr.pocketcore.core

import android.content.Context
import java.io.File

/**
 * Writes the bitcoin.conf used by the bundled daemon.
 *
 * The file is regenerated on every start so it always matches the current
 * settings, and it is intentionally opinionated: mobile defaults, loopback-only
 * RPC, no wallet, pruned storage.
 *
 * Bitcoin Core only reads network-specific options such as rpcport, port,
 * rpcbind and rpcallowip from the section of the selected network, which is why
 * the generated file ends with a [main] / [signet] / testnet4 block. The ports
 * are also passed on the command line (which wins over the file) so a section
 * that fails to parse can never leave the daemon on a different endpoint than
 * the one the app talks to.
 */
object NodeConfig {

    fun write(context: Context, settings: NodeSettingsState, rpcPort: Int, p2pPort: Int) {
        val conf = NodePaths.confFile(context)
        val network = settings.network
        val text = buildString {
            appendLine("# Generated by POCKETCORE. Changes are overwritten on every start.")
            appendLine("server=1")
            appendLine("daemon=0")
            appendLine("chain=${network.chainArg}")
            appendLine("rpcuser=${settings.rpcUser}")
            appendLine("rpcpassword=${settings.rpcPassword}")
            appendLine("prune=${settings.pruneMb}")
            appendLine("dbcache=128")
            appendLine("maxconnections=8")
            appendLine("maxmempool=50")
            appendLine("persistmempool=1")
            appendLine("listen=1")
            appendLine("discover=0")
            appendLine("dnsseed=1")
            appendLine("uacomment=POCKETCORE")
            appendLine("disablewallet=1")
            appendLine("txindex=0")
            appendLine("blockfilterindex=0")
            appendLine("peerbloomfilters=0")
            appendLine("printtoconsole=0")
            appendLine("")
            appendLine("[${network.chainArg}]")
            appendLine("rpcbind=127.0.0.1")
            appendLine("rpcallowip=127.0.0.1")
            appendLine("rpcport=$rpcPort")
            appendLine("port=$p2pPort")
        }
        conf.writeText(text)
    }

    /** A copy-pasteable description of the local RPC endpoint. */
    fun rpcSnippet(settings: NodeSettingsState, rpcPort: Int): String = buildString {
        appendLine("Network: ${settings.network.label}")
        appendLine("Host: 127.0.0.1")
        appendLine("Port: $rpcPort")
        appendLine("User: ${settings.rpcUser}")
        appendLine("Password: ${settings.rpcPassword}")
        appendLine("Endpoint: http://127.0.0.1:$rpcPort/")
    }

    /** bitcoin.conf lines an external wallet or tool needs for this node. */
    fun clientConf(settings: NodeSettingsState, rpcPort: Int): String = buildString {
        appendLine("rpcconnect=127.0.0.1")
        appendLine("rpcport=$rpcPort")
        appendLine("rpcuser=${settings.rpcUser}")
        appendLine("rpcpassword=${settings.rpcPassword}")
    }

    fun snapshotTarget(context: Context, displayName: String): File {
        val safe = displayName.replace(Regex("[^A-Za-z0-9._-]"), "_").ifBlank { "snapshot.dat" }
        val name = if (safe.endsWith(".dat")) safe else "$safe.dat"
        return File(NodePaths.snapshotDir(context), name)
    }
}
